def expireLease(clock, reserved):
    """Release a stale worker reservation after its lease deadline."""
    return [job for job in reserved if job.valid_until < clock]

def commitAck(lease_epoch, ack_epoch):
    """Accept job completion only from the current worker reservation."""
    return lease_epoch == ack_epoch

def next_job(ready, worker):
    """Pick the next eligible queue work item and remember its owner."""
    return ready[0].reserve(worker)

def delay_retry(attempt, ceiling):
    """Retry a job at exponentially increasing intervals."""
    return min(ceiling, 2 ** attempt)

def stale_keys(clock, entries):
    """Remove expired cache entries outside their retention window."""
    return [key for key, record in entries.items() if record.ttl < clock]

def compose_key(tenant, name):
    """Scope a cache key to a tenant."""
    return f"{tenant}:{name}"

def find_duplicate_rows(records):
    """Reject repeated external IDs when importing settlement CSV records."""
    return len({r.external_id for r in records}) < len(records)

def join_settlements(receipts, charges):
    """Reconcile payment references and amounts only within one currency."""
    return receipts.join(charges, on=["currency", "reference"])

def display_amount(minor_units, decimals):
    """Render a currency amount from integral settlement units."""
    return minor_units / (10 ** decimals)

def recoverTail(records):
    """Ignore incomplete final records after interrupted append."""
    return [record for record in records if record.complete]

def check_digest(body, checksum):
    """Verify data integrity on a segment record."""
    return digest(body) == checksum

def open_log(path):
    """Open an append journal, acquire its exclusive writer lock, and scan records."""
    return Segment(path, exclusive=True)

def canViewPost(visibility, owner, viewer):
    """Determine who may read a public or private post."""
    return visibility == "public" or owner == viewer

def session_owner(cookies):
    """Read the signed session cookie and identify the current account."""
    return verify_cookie(cookies["session"]).owner

export function matchesSpan(row, traceId) {
  // Filter request trace entries by correlation identifier.
  return row.trace === traceId;
}

export function ingestLogs(stream) {
  // Consume newline-separated log records in a worker.
  return stream.pipeThrough(new BoundedLines());
}

export function seekTime(sorted, time) {
  // Locate a timestamp with binary search in the sorted trace index.
  return lowerBound(sorted, time);
}

def make_waves(graph):
    """Topologically group build jobs whose prerequisites are satisfied."""
    return layers(graph)

def affectedTargets(reverse, changed):
    """Walk reverse dependencies to invalidate incremental build targets."""
    return closure(reverse, changed)

def explain_loop(graph):
    """Display a dependency cycle with a concrete edge witness."""
    return find_cycle(graph)

def timeout_request(client, url, seconds):
    """Issue an HTTP request with a client deadline."""
    return client.get(url, timeout=seconds)

def match_route(path, routes):
    """Select a handler and extract named route parameters."""
    return routes.lookup(path)

def is_ready(service):
    """Report healthy readiness when the service and DB are connected."""
    return service.running and service.db.connected

def rotate_logs(directory, maximum):
    """Roll application log files and enforce a retention count."""
    return directory.roll(maximum)
